-- Repair migration for production environments where the original combined migration rolled back.
create table if not exists public.operator_personal_purchases (
 id uuid primary key default gen_random_uuid(), person_id uuid not null references public.team_members(id), product_id uuid not null references public.products(id), storage_location_id uuid not null references public.storage_locations(id), quantity integer not null check(quantity>0), unit_price_lyd numeric(12,2) not null check(unit_price_lyd>=0), total_lyd numeric(12,2) generated always as(round(quantity*unit_price_lyd,2)) stored, note text, inventory_movement_id uuid references public.inventory_movements(id), client_submission_id text not null unique, created_by uuid not null references public.team_members(id), purchased_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.operator_debt_payments (
 id uuid primary key default gen_random_uuid(), person_id uuid not null references public.team_members(id), amount_lyd numeric(12,2) not null check(amount_lyd>0), paid_at timestamptz not null, payment_method text not null, note text, client_submission_id text not null unique, recorded_by uuid not null references public.team_members(id), created_at timestamptz not null default now());
create table if not exists public.operator_advances (
 id uuid primary key default gen_random_uuid(), person_id uuid not null references public.team_members(id), amount_lyd numeric(12,2) not null check(amount_lyd>0), given_at timestamptz not null, purpose text not null, note text, client_submission_id text not null unique, issued_by uuid not null references public.team_members(id), created_at timestamptz not null default now());
create table if not exists public.operator_expenses (
 id uuid primary key default gen_random_uuid(), person_id uuid not null references public.team_members(id), advance_id uuid references public.operator_advances(id), amount_lyd numeric(12,2) not null check(amount_lyd>0), expense_type text not null, supplier_payee text not null, spent_at timestamptz not null, receipt_url text, note text not null, status text not null default 'submitted' check(status in('submitted','approved','rejected')), review_note text, reviewed_by uuid references public.team_members(id), reviewed_at timestamptz, client_submission_id text not null unique, submitted_by uuid not null references public.team_members(id), created_at timestamptz not null default now());
create table if not exists public.operator_advance_returns (
 id uuid primary key default gen_random_uuid(), person_id uuid not null references public.team_members(id), advance_id uuid references public.operator_advances(id), amount_lyd numeric(12,2) not null check(amount_lyd>0), returned_at timestamptz not null, payment_method text not null, note text, client_submission_id text not null unique, recorded_by uuid not null references public.team_members(id), created_at timestamptz not null default now());

create or replace function public.snacky_operator_money_is_manager() returns boolean language sql stable security definer set search_path=public,auth as $$select public.snacky_current_profile_has_any_role(array['owner','admin'])$$;
create or replace function public.snacky_operator_money_can_view(p_person_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$select public.snacky_operator_money_is_manager() or public.snacky_current_team_member_id()=p_person_id$$;

alter table public.operator_personal_purchases enable row level security;
alter table public.operator_debt_payments enable row level security;
alter table public.operator_advances enable row level security;
alter table public.operator_expenses enable row level security;
alter table public.operator_advance_returns enable row level security;
drop policy if exists operator_personal_purchases_read on public.operator_personal_purchases;
create policy operator_personal_purchases_read on public.operator_personal_purchases for select to authenticated using(public.snacky_operator_money_can_view(person_id));
drop policy if exists operator_debt_payments_read on public.operator_debt_payments;
create policy operator_debt_payments_read on public.operator_debt_payments for select to authenticated using(public.snacky_operator_money_can_view(person_id));
drop policy if exists operator_advances_read on public.operator_advances;
create policy operator_advances_read on public.operator_advances for select to authenticated using(public.snacky_operator_money_can_view(person_id));
drop policy if exists operator_expenses_read on public.operator_expenses;
create policy operator_expenses_read on public.operator_expenses for select to authenticated using(public.snacky_operator_money_can_view(person_id));
drop policy if exists operator_advance_returns_read on public.operator_advance_returns;
create policy operator_advance_returns_read on public.operator_advance_returns for select to authenticated using(public.snacky_operator_money_can_view(person_id));

drop view if exists public.operator_money_balances;
create view public.operator_money_balances as select tm.id person_id,tm.full_name,
 coalesce((select sum(total_lyd) from public.operator_personal_purchases where person_id=tm.id),0)::numeric(12,2) personal_purchases_lyd,
 coalesce((select sum(amount_lyd) from public.operator_debt_payments where person_id=tm.id),0)::numeric(12,2) debt_paid_lyd,
 (coalesce((select sum(total_lyd) from public.operator_personal_purchases where person_id=tm.id),0)-coalesce((select sum(amount_lyd) from public.operator_debt_payments where person_id=tm.id),0))::numeric(12,2) personal_debt_remaining_lyd,
 coalesce((select sum(amount_lyd) from public.operator_advances where person_id=tm.id),0)::numeric(12,2) advanced_lyd,
 coalesce((select sum(amount_lyd) from public.operator_expenses where person_id=tm.id and status='approved'),0)::numeric(12,2) approved_expenses_lyd,
 coalesce((select sum(amount_lyd) from public.operator_advance_returns where person_id=tm.id),0)::numeric(12,2) returned_money_lyd,
 (coalesce((select sum(amount_lyd) from public.operator_advances where person_id=tm.id),0)-coalesce((select sum(amount_lyd) from public.operator_expenses where person_id=tm.id and status='approved'),0)-coalesce((select sum(amount_lyd) from public.operator_advance_returns where person_id=tm.id),0))::numeric(12,2) unaccounted_advance_lyd from public.team_members tm;
grant select on public.operator_money_balances to authenticated;

create or replace function public.operator_money_reserved_qty(p_product_id uuid) returns integer language sql stable security definer set search_path=public,auth as $$select coalesce(sum(i.planned_quantity),0)::integer from public.route_stop_items i join public.routes r on r.id=i.route_id where i.product_id=p_product_id and r.status::text in('draft','planned','assigned','ready','pending_pickup')$$;

create or replace function public.create_operator_personal_purchase(p_person_id uuid,p_product_id uuid,p_storage_location_id uuid,p_quantity integer,p_unit_price_lyd numeric,p_note text,p_client_submission_id text) returns public.operator_personal_purchases language plpgsql security definer set search_path=public,auth as $$
declare a uuid:=public.snacky_current_team_member_id(); m boolean:=public.snacky_operator_money_is_manager(); q integer; reserved integer; price numeric; row public.operator_personal_purchases; movement uuid;
begin if a is null then raise exception 'Not authenticated' using errcode='28000'; end if; if not m and a<>p_person_id then raise exception 'Operators can only buy for themselves' using errcode='42501'; end if;
 select * into row from public.operator_personal_purchases where client_submission_id=p_client_submission_id; if found then return row; end if;
 select coalesce(p_unit_price_lyd,current_selling_price_lyd,selling_price,0) into price from public.products where id=p_product_id and active=true; if not found then raise exception 'Product not found'; end if;
 select coalesce(quantity_on_hand,0)::integer into q from public.current_inventory_by_location where location_type='storage' and location_id=p_storage_location_id and product_id=p_product_id; reserved:=public.operator_money_reserved_qty(p_product_id); if greatest(coalesce(q,0)-reserved,0)<p_quantity then raise exception 'Not enough genuinely available storage stock after route reservations' using errcode='23514'; end if;
 insert into public.inventory_movements(product_id,quantity,from_entity_type,from_entity_id,to_entity_type,to_entity_id,reason,idempotency_key,source_type,created_by,notes) values(p_product_id,p_quantity,'storage',p_storage_location_id,'operator_personal_purchase',p_person_id,'operator_personal_purchase',p_client_submission_id,'operator_personal_purchase',a,coalesce(p_note,'Operator personal purchase')) returning id into movement;
 insert into public.operator_personal_purchases(person_id,product_id,storage_location_id,quantity,unit_price_lyd,note,inventory_movement_id,client_submission_id,created_by) values(p_person_id,p_product_id,p_storage_location_id,p_quantity,price,nullif(trim(coalesce(p_note,'')),''),movement,p_client_submission_id,a) returning * into row; return row; end$$;
grant execute on function public.create_operator_personal_purchase(uuid,uuid,uuid,integer,numeric,text,text) to authenticated;

create or replace function public.create_operator_advance(p_person_id uuid,p_amount numeric,p_given_at timestamptz,p_purpose text,p_note text,p_client_submission_id text) returns public.operator_advances language plpgsql security definer set search_path=public,auth as $$declare a uuid:=public.snacky_current_team_member_id(); row public.operator_advances; begin if not public.snacky_operator_money_is_manager() then raise exception 'Only owner/admin can give money' using errcode='42501'; end if; select * into row from public.operator_advances where client_submission_id=p_client_submission_id;if found then return row;end if;insert into public.operator_advances(person_id,amount_lyd,given_at,purpose,note,client_submission_id,issued_by) values(p_person_id,p_amount,p_given_at,p_purpose,nullif(trim(coalesce(p_note,'')),''),p_client_submission_id,a) returning * into row;return row;end$$;
grant execute on function public.create_operator_advance(uuid,numeric,timestamptz,text,text,text) to authenticated;

create or replace function public.submit_operator_expense(p_person_id uuid,p_advance_id uuid,p_amount numeric,p_expense_type text,p_supplier_payee text,p_spent_at timestamptz,p_receipt_url text,p_note text,p_client_submission_id text) returns public.operator_expenses language plpgsql security definer set search_path=public,auth as $$declare a uuid:=public.snacky_current_team_member_id();row public.operator_expenses;begin if not public.snacky_operator_money_is_manager() and a<>p_person_id then raise exception 'Operators can only submit their own expense' using errcode='42501';end if;select * into row from public.operator_expenses where client_submission_id=p_client_submission_id;if found then return row;end if;insert into public.operator_expenses(person_id,advance_id,amount_lyd,expense_type,supplier_payee,spent_at,receipt_url,note,client_submission_id,submitted_by) values(p_person_id,p_advance_id,p_amount,p_expense_type,p_supplier_payee,p_spent_at,nullif(trim(coalesce(p_receipt_url,'')),''),p_note,p_client_submission_id,a) returning * into row;return row;end$$;
grant execute on function public.submit_operator_expense(uuid,uuid,numeric,text,text,timestamptz,text,text,text) to authenticated;

create or replace function public.review_operator_expense(p_expense_id uuid,p_status text,p_review_note text) returns public.operator_expenses language plpgsql security definer set search_path=public,auth as $$declare a uuid:=public.snacky_current_team_member_id();row public.operator_expenses;begin if not public.snacky_operator_money_is_manager() then raise exception 'Only owner/admin can review expenses' using errcode='42501';end if;if p_status not in('approved','rejected') then raise exception 'Invalid status';end if;update public.operator_expenses set status=p_status,review_note=nullif(trim(coalesce(p_review_note,'')),''),reviewed_by=a,reviewed_at=now() where id=p_expense_id and status='submitted' returning * into row;if not found then raise exception 'Expense already reviewed or missing';end if;return row;end$$;
grant execute on function public.review_operator_expense(uuid,text,text) to authenticated;

create or replace function public.record_operator_debt_payment(p_person_id uuid,p_amount numeric,p_paid_at timestamptz,p_payment_method text,p_note text,p_client_submission_id text) returns public.operator_debt_payments language plpgsql security definer set search_path=public,auth as $$declare a uuid:=public.snacky_current_team_member_id();due numeric;row public.operator_debt_payments;begin if not public.snacky_operator_money_is_manager() then raise exception 'Only owner/admin can record payment' using errcode='42501';end if;select * into row from public.operator_debt_payments where client_submission_id=p_client_submission_id;if found then return row;end if;select personal_debt_remaining_lyd into due from public.operator_money_balances where person_id=p_person_id;if p_amount<=0 or p_amount>greatest(due,0) then raise exception 'Payment exceeds remaining debt' using errcode='23514';end if;insert into public.operator_debt_payments(person_id,amount_lyd,paid_at,payment_method,note,client_submission_id,recorded_by) values(p_person_id,p_amount,p_paid_at,p_payment_method,nullif(trim(coalesce(p_note,'')),''),p_client_submission_id,a) returning * into row;return row;end$$;
grant execute on function public.record_operator_debt_payment(uuid,numeric,timestamptz,text,text,text) to authenticated;

create or replace function public.record_operator_advance_return(p_person_id uuid,p_advance_id uuid,p_amount numeric,p_returned_at timestamptz,p_payment_method text,p_note text,p_client_submission_id text) returns public.operator_advance_returns language plpgsql security definer set search_path=public,auth as $$declare a uuid:=public.snacky_current_team_member_id();bal numeric;row public.operator_advance_returns;begin if not public.snacky_operator_money_is_manager() then raise exception 'Only owner/admin can record returned money' using errcode='42501';end if;select * into row from public.operator_advance_returns where client_submission_id=p_client_submission_id;if found then return row;end if;select unaccounted_advance_lyd into bal from public.operator_money_balances where person_id=p_person_id;if p_amount<=0 or p_amount>greatest(bal,0) then raise exception 'Return exceeds unaccounted advance' using errcode='23514';end if;insert into public.operator_advance_returns(person_id,advance_id,amount_lyd,returned_at,payment_method,note,client_submission_id,recorded_by) values(p_person_id,p_advance_id,p_amount,p_returned_at,p_payment_method,nullif(trim(coalesce(p_note,'')),''),p_client_submission_id,a) returning * into row;return row;end$$;
grant execute on function public.record_operator_advance_return(uuid,uuid,numeric,timestamptz,text,text,text) to authenticated;
